/// The `VkSamplerCreateInfo` of an `ImageSamplingInstanceParams` with the structures chained to it.
#[derive(Clone, Debug)]
pub struct SamplerParams {
    pub mag_filter: vk::Filter,
    pub min_filter: vk::Filter,
    pub mipmap_mode: vk::SamplerMipmapMode,
    pub address_mode_u: vk::SamplerAddressMode,
    pub address_mode_v: vk::SamplerAddressMode,
    pub address_mode_w: vk::SamplerAddressMode,
    pub mip_lod_bias: f32,
    pub anisotropy_enable: bool,
    pub max_anisotropy: f32,
    pub compare_enable: bool,
    pub compare_op: vk::CompareOp,
    pub min_lod: f32,
    pub max_lod: f32,
    pub border_color: vk::BorderColor,
    pub unnormalized_coordinates: bool,
    /// `VkSamplerReductionModeCreateInfo`
    pub reduction_mode: Option<vk::SamplerReductionMode>,
    /// `VkSamplerCustomBorderColorCreateInfoEXT`: the colour and the format it is for (`UNDEFINED` when formatless)
    pub custom_border_color: Option<(BorderValue, vk::Format)>,
}

impl SamplerParams {
    /// `SamplerTest::getSamplerCreateInfo`'s `defaultSamplerParams`
    pub fn default_params(border_color: vk::BorderColor, max_lod: f32, unnormalized_coordinates: bool) -> Self {
        Self {
            mag_filter: vk::Filter::NEAREST,
            min_filter: vk::Filter::NEAREST,
            mipmap_mode: vk::SamplerMipmapMode::NEAREST,
            address_mode_u: vk::SamplerAddressMode::CLAMP_TO_EDGE,
            address_mode_v: vk::SamplerAddressMode::CLAMP_TO_EDGE,
            address_mode_w: vk::SamplerAddressMode::CLAMP_TO_EDGE,
            mip_lod_bias: 0.0,
            anisotropy_enable: false,
            max_anisotropy: 1.0,
            compare_enable: false,
            compare_op: vk::CompareOp::NEVER,
            min_lod: 0.0,
            max_lod,
            border_color,
            unnormalized_coordinates,
            reduction_mode: None,
            custom_border_color: None,
        }
    }

    /// `createSampler`
    pub fn create<'a>(&self, device: &'a Device) -> Result<Unique<'a, vk::Sampler>, TestError> {
        let mut reduction_info = vk::SamplerReductionModeCreateInfo::builder().reduction_mode(
            self.reduction_mode
                .unwrap_or(vk::SamplerReductionMode::WEIGHTED_AVERAGE),
        );
        let custom_color = self
            .custom_border_color
            .unwrap_or((BorderValue::default(), vk::Format::UNDEFINED));
        let mut custom_info = vk::SamplerCustomBorderColorCreateInfoEXT::builder()
            .custom_border_color(vk::ClearColorValue {
                uint32: custom_color.0.0,
            })
            .format(custom_color.1);

        let mut info = vk::SamplerCreateInfo::builder()
            .mag_filter(self.mag_filter)
            .min_filter(self.min_filter)
            .mipmap_mode(self.mipmap_mode)
            .address_mode_u(self.address_mode_u)
            .address_mode_v(self.address_mode_v)
            .address_mode_w(self.address_mode_w)
            .mip_lod_bias(self.mip_lod_bias)
            .anisotropy_enable(self.anisotropy_enable)
            .max_anisotropy(self.max_anisotropy)
            .compare_enable(self.compare_enable)
            .compare_op(self.compare_op)
            .min_lod(self.min_lod)
            .max_lod(self.max_lod)
            .border_color(self.border_color)
            .unnormalized_coordinates(self.unnormalized_coordinates);
        if self.reduction_mode.is_some() {
            info = info.push_next(&mut reduction_info);
        }
        if self.custom_border_color.is_some() {
            info = info.push_next(&mut custom_info);
        }

        let sampler = unsafe { device.create_sampler(&info, None) }.vk_check("vkCreateSampler")?;
        Ok(Unique::new(device, sampler))
    }

    /// The border colour `mapVkSampler` puts in the `tcu::Sampler`.
    fn tcu_border_color(&self) -> BorderValue {
        let uint = |v: [u32; 4]| BorderValue(v);
        let float = |v: [f32; 4]| BorderValue(v.map(f32::to_bits));
        match self.border_color {
            vk::BorderColor::INT_OPAQUE_BLACK => uint([0, 0, 0, 1]),
            vk::BorderColor::FLOAT_OPAQUE_BLACK => float([0.0, 0.0, 0.0, 1.0]),
            vk::BorderColor::INT_OPAQUE_WHITE => uint([1, 1, 1, 1]),
            vk::BorderColor::FLOAT_OPAQUE_WHITE => float([1.0, 1.0, 1.0, 1.0]),
            vk::BorderColor::INT_TRANSPARENT_BLACK => uint([0, 0, 0, 0]),
            vk::BorderColor::FLOAT_TRANSPARENT_BLACK => float([0.0, 0.0, 0.0, 0.0]),
            _ => self
                .custom_border_color
                .map_or_else(BorderValue::default, |(value, _)| value),
        }
    }
}

/// `mapVkSamplerAddressMode`
pub fn map_vk_sampler_address_mode(mode: vk::SamplerAddressMode) -> WrapMode {
    match mode {
        vk::SamplerAddressMode::CLAMP_TO_BORDER => WrapMode::ClampToBorder,
        vk::SamplerAddressMode::MIRRORED_REPEAT => WrapMode::MirroredRepeat,
        vk::SamplerAddressMode::MIRROR_CLAMP_TO_EDGE => WrapMode::MirroredOnce,
        vk::SamplerAddressMode::REPEAT => WrapMode::Repeat,
        _ => WrapMode::ClampToEdge,
    }
}

/// `mapVkMinTexFilter`
fn map_vk_min_tex_filter(filter: vk::Filter, mip_mode: vk::SamplerMipmapMode) -> MinFilterMode {
    match (filter == vk::Filter::LINEAR, mip_mode == vk::SamplerMipmapMode::LINEAR) {
        (true, true) => MinFilterMode::LinearMipmapLinear,
        (true, false) => MinFilterMode::LinearMipmapNearest,
        (false, true) => MinFilterMode::NearestMipmapLinear,
        (false, false) => MinFilterMode::NearestMipmapNearest,
    }
}

