// ImageSamplingInstance
// ---------------------------------------------------------------------------------------------------------------------------

/// The vertex and fragment shader objects of a shader object construction type: both created in one call (with the link flag
/// when linked), and for the binary types created again from the binaries the first ones return. Both take the descriptor set
/// layout and push constant range of the fragment shader, as `GraphicsPipelineWrapper::makeShaderCreateInfo` does.
fn create_graphics_shader_objects<'a>(
    context: &'a Context<'a>,
    construction: PipelineConstructionType,
    vert: ProgramBinary,
    frag: ProgramBinary,
    set_layout: vk::DescriptorSetLayout,
    push_constant_range: vk::PushConstantRange,
) -> Result<(ShaderObject<'a>, ShaderObject<'a>), TestError> {
    let device = context.get_device();
    let features = context.get_device_features();
    let set_layouts = [set_layout];
    let push_constant_ranges = [push_constant_range];
    let linked = construction.is_shader_object_linked();
    let flags = if linked {
        vk::ShaderCreateFlagsEXT::LINK_STAGE
    } else {
        vk::ShaderCreateFlagsEXT::empty()
    };
    let vertex_next_stage = if linked {
        vk::ShaderStageFlags::FRAGMENT
    } else {
        get_shader_object_next_stages(
            vk::ShaderStageFlags::VERTEX,
            features.tessellation_shader == vk::TRUE,
            features.geometry_shader == vk::TRUE,
        )
    };

    let create = |vertex: (vk::ShaderCodeTypeEXT, usize, *const std::ffi::c_void),
                  fragment: (vk::ShaderCodeTypeEXT, usize, *const std::ffi::c_void)|
     -> Result<(ShaderObject<'a>, ShaderObject<'a>), TestError> {
        let infos = [
            shader_create_info(
                flags,
                vk::ShaderStageFlags::VERTEX,
                vertex_next_stage,
                vertex.0,
                vertex.1,
                vertex.2,
                &set_layouts,
                &push_constant_ranges,
            ),
            shader_create_info(
                flags,
                vk::ShaderStageFlags::FRAGMENT,
                vk::ShaderStageFlags::empty(),
                fragment.0,
                fragment.1,
                fragment.2,
                &set_layouts,
                &push_constant_ranges,
            ),
        ];
        let (shaders, _) = unsafe { device.create_shaders_ext(&infos, None) }.vk_check("vkCreateShadersEXT")?;
        Ok((
            ShaderObject::new(device, shaders[0]),
            ShaderObject::new(device, shaders[1]),
        ))
    };

    let (vertex, fragment) = create(
        (
            vk::ShaderCodeTypeEXT::SPIRV,
            std::mem::size_of_val(vert.spirv),
            vert.spirv.as_ptr().cast(),
        ),
        (
            vk::ShaderCodeTypeEXT::SPIRV,
            std::mem::size_of_val(frag.spirv),
            frag.spirv.as_ptr().cast(),
        ),
    )?;
    if !construction.is_shader_object_binary() {
        return Ok((vertex, fragment));
    }

    let vertex_binary = get_shader_binary_data(device, vertex.get())?;
    let fragment_binary = get_shader_binary_data(device, fragment.get())?;
    create(
        (
            vk::ShaderCodeTypeEXT::BINARY,
            vertex_binary.len(),
            vertex_binary.as_ptr().cast(),
        ),
        (
            vk::ShaderCodeTypeEXT::BINARY,
            fragment_binary.len(),
            fragment_binary.as_ptr().cast(),
        ),
    )
}

/// The compute shader object of a shader object construction type, from SPIR-V or from the binary of a first one.
fn create_compute_shader_object<'a>(
    device: &'a Device,
    construction: PipelineConstructionType,
    comp: ProgramBinary,
    set_layout: vk::DescriptorSetLayout,
    push_constant_range: vk::PushConstantRange,
) -> Result<ShaderObject<'a>, TestError> {
    let set_layouts = [set_layout];
    let push_constant_ranges = [push_constant_range];
    let create = |code_type: vk::ShaderCodeTypeEXT,
                  size: usize,
                  code: *const std::ffi::c_void|
     -> Result<ShaderObject<'a>, TestError> {
        let info = shader_create_info(
            vk::ShaderCreateFlagsEXT::empty(),
            vk::ShaderStageFlags::COMPUTE,
            vk::ShaderStageFlags::empty(),
            code_type,
            size,
            code,
            &set_layouts,
            &push_constant_ranges,
        );
        let (shaders, _) = unsafe { device.create_shaders_ext(&[info], None) }.vk_check("vkCreateShadersEXT")?;
        Ok(ShaderObject::new(device, shaders[0]))
    };

    let shader = create(
        vk::ShaderCodeTypeEXT::SPIRV,
        std::mem::size_of_val(comp.spirv),
        comp.spirv.as_ptr().cast(),
    )?;
    if !construction.is_shader_object_binary() {
        return Ok(shader);
    }
    let binary = get_shader_binary_data(device, shader.get())?;
    create(vk::ShaderCodeTypeEXT::BINARY, binary.len(), binary.as_ptr().cast())
}

/// `ImageSamplingInstance`
pub struct ImageSamplingInstance<'a> {
    context: &'a Context<'a>,
    params: ImageSamplingInstanceParams,
}

impl<'a> ImageSamplingInstance<'a> {
    pub fn new(context: &'a Context<'a>, params: ImageSamplingInstanceParams) -> Self {
        Self { context, params }
    }

    /// `m_colorFormat`: float16 for the ASTC HDR formats, to keep their precision.
    fn color_format(&self) -> vk::Format {
        if is_astc_hdr_format(self.params.image_format) {
            vk::Format::R16G16B16A16_SFLOAT
        } else {
            vk::Format::R8G8B8A8_UNORM
        }
    }

    /// `ImageSamplingInstance::iterate`
    pub fn run(&self) -> TestOutcome {
        let context = self.context;
        let params = &self.params;
        let device = context.get_device();
        let allocator = context.get_default_allocator();
        let (queue, queue_family_index) = if params.use_compute {
            context
                .get_compute_queue()
                .ok_or_else(|| TestError::NotSupported("Exclusive compute queue not supported.".to_string()))?
        } else {
            (
                context.get_universal_queue(),
                context.get_universal_queue_family_index(),
            )
        };
        let queue_family_indices = [queue_family_index];
        let image_count = params.image_count as usize;
        let color_format = self.color_format();
        let render_size = params.render_size;
        let image_view_type = params.image_view_type;
        let sampler_params = &params.sampler_params;

        // The component mask: with min/max reduction and no filterMinmaxImageComponentMapping, only the R component is defined.
        let mut component_mask = [true; 4];
        if sampler_params.reduction_mode.is_some() {
            let mut minmax_properties = vk::PhysicalDeviceSamplerFilterMinmaxProperties::default();
            let mut properties2 = vk::PhysicalDeviceProperties2::builder().push_next(&mut minmax_properties);
            unsafe {
                context
                    .get_instance()
                    .get_physical_device_properties2(context.get_physical_device(), &mut properties2)
            };
            if minmax_properties.filter_minmax_image_component_mapping != vk::TRUE {
                component_mask = [true, false, false, false];
            }
        }
        if is_astc_3d_format(params.image_format) || is_astc_hdr_format(params.image_format) {
            return Err(TestError::NotPorted(format!(
                "sampling {:?}: the decoder handles neither HDR nor 3D ASTC",
                params.image_format
            )));
        }

        // Create texture images, views and samplers
        let image_flags =
            if image_view_type == vk::ImageViewType::CUBE || image_view_type == vk::ImageViewType::CUBE_ARRAY {
                vk::ImageCreateFlags::CUBE_COMPATIBLE
            } else {
                vk::ImageCreateFlags::empty()
            };
        let texture = create_test_texture(
            params.image_format,
            image_view_type,
            params.image_size,
            params.layer_count,
        )?;

        let image_info = vk::ImageCreateInfo::builder()
            .flags(image_flags)
            .image_type(get_compatible_image_type(image_view_type))
            .format(params.image_format)
            .extent(vk::Extent3D {
                width: params.image_size[0] as u32,
                height: params.image_size[1] as u32,
                depth: params.image_size[2] as u32,
            })
            .mip_levels(texture.get_num_levels() as u32)
            .array_layers(params.layer_count as u32)
            .samples(vk::SampleCountFlags::_1)
            .tiling(vk::ImageTiling::OPTIMAL)
            .usage(vk::ImageUsageFlags::SAMPLED | vk::ImageUsageFlags::TRANSFER_DST)
            .sharing_mode(vk::SharingMode::EXCLUSIVE)
            .queue_family_indices(&queue_family_indices)
            .initial_layout(vk::ImageLayout::UNDEFINED)
            .build();

        let create_image = |info: vk::ImageCreateInfo| match params.allocation_kind {
            AllocationKind::Suballocated => ImageWithMemory::new(device, allocator, info, MemoryRequirement::ANY),
            AllocationKind::Dedicated => {
                ImageWithMemory::new_dedicated(device, allocator, info, MemoryRequirement::ANY)
            }
        };

        let mut images = Vec::with_capacity(image_count);
        let mut image_views = Vec::with_capacity(image_count);
        for _ in 0..image_count {
            let image = create_image(image_info)?;

            // Upload texture data
            upload_test_texture(
                context,
                queue,
                queue_family_index,
                &texture,
                image.get(),
                params.image_layout,
                vk::PipelineStageFlags::ALL_COMMANDS,
            )?;

            // Create image view and sampler
            let view_info = vk::ImageViewCreateInfo::builder()
                .image(image.get())
                .view_type(image_view_type)
                .format(params.image_format)
                .components(params.component_mapping)
                .subresource_range(params.subresource_range);
            let view = unsafe { device.create_image_view(&view_info, None) }.vk_check("vkCreateImageView")?;
            image_views.push(Unique::new(device, view));
            images.push(image);
        }
        let sampler = sampler_params.create(device)?;

        // Create color images and views
        let mut color_usage = vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC;
        if params.use_compute {
            color_usage |= vk::ImageUsageFlags::STORAGE;
        }
        let color_image_info = vk::ImageCreateInfo::builder()
            .image_type(vk::ImageType::_2D)
            .format(color_format)
            .extent(vk::Extent3D {
                width: render_size[0],
                height: render_size[1],
                depth: 1,
            })
            .mip_levels(1)
            .array_layers(1)
            .samples(vk::SampleCountFlags::_1)
            .tiling(vk::ImageTiling::OPTIMAL)
            .usage(color_usage)
            .sharing_mode(vk::SharingMode::EXCLUSIVE)
            .queue_family_indices(&queue_family_indices)
            .initial_layout(vk::ImageLayout::UNDEFINED)
            .build();
        let component_mapping_rgba = vk::ComponentMapping {
            r: vk::ComponentSwizzle::R,
            g: vk::ComponentSwizzle::G,
            b: vk::ComponentSwizzle::B,
            a: vk::ComponentSwizzle::A,
        };

        let mut color_images = Vec::with_capacity(image_count);
        let mut color_attachment_views = Vec::with_capacity(image_count);
        for _ in 0..image_count {
            let color_image = create_image(color_image_info)?;
            let view_info = vk::ImageViewCreateInfo::builder()
                .image(color_image.get())
                .view_type(vk::ImageViewType::_2D)
                .format(color_format)
                .components(component_mapping_rgba)
                .subresource_range(vk::ImageSubresourceRange {
                    aspect_mask: vk::ImageAspectFlags::COLOR,
                    base_mip_level: 0,
                    level_count: 1,
                    base_array_layer: 0,
                    layer_count: 1,
                });
            let view = unsafe { device.create_image_view(&view_info, None) }.vk_check("vkCreateImageView")?;
            color_attachment_views.push(Unique::new(device, view));
            color_images.push(color_image);
        }

        // Create vertex buffer (for compute only a storage buffer with the vertices)
        let buffer_usage = if params.use_compute {
            vk::BufferUsageFlags::STORAGE_BUFFER
        } else {
            vk::BufferUsageFlags::VERTEX_BUFFER
        };
        let vertex_buffer_size = std::mem::size_of_val(params.vertices.as_slice()) as vk::DeviceSize;
        let vertex_buffer_info = make_buffer_create_info(vertex_buffer_size, buffer_usage);
        let vertex_buffer = match params.allocation_kind {
            AllocationKind::Suballocated => {
                BufferWithMemory::new(device, allocator, vertex_buffer_info, MemoryRequirement::HOST_VISIBLE)?
            }
            AllocationKind::Dedicated => {
                BufferWithMemory::new_dedicated(device, allocator, vertex_buffer_info, MemoryRequirement::HOST_VISIBLE)?
            }
        };
        // Load vertices into the vertex buffer
        unsafe {
            std::ptr::copy_nonoverlapping(
                params.vertices.as_ptr().cast::<u8>(),
                vertex_buffer.get_allocation().get_host_ptr(),
                vertex_buffer_size as usize,
            )
        };
        flush_alloc(device, vertex_buffer.get_allocation())?;

        // Create descriptor set for image and sampler
        let separate_sampler = params.sampling_type == vk::DescriptorType::SAMPLED_IMAGE;
        let mut pool_builder = DescriptorPoolBuilder::new();
        if separate_sampler {
            pool_builder = pool_builder.add_type(vk::DescriptorType::SAMPLER, 1);
        }
        pool_builder = pool_builder.add_type(params.sampling_type, params.image_count);
        if params.use_compute {
            pool_builder = pool_builder
                .add_type(vk::DescriptorType::STORAGE_IMAGE, params.image_count)
                .add_type(vk::DescriptorType::STORAGE_BUFFER, 1);
        }
        let descriptor_pool = pool_builder.build(
            device,
            vk::DescriptorPoolCreateFlags::FREE_DESCRIPTOR_SET,
            if separate_sampler {
                params.image_count + 1
            } else {
                params.image_count
            },
        )?;

        let stage_flags = if params.use_compute {
            vk::ShaderStageFlags::COMPUTE
        } else {
            vk::ShaderStageFlags::FRAGMENT
        };
        let mut layout_builder = DescriptorSetLayoutBuilder::new();
        let image_binding = if separate_sampler { 1 } else { 0 };
        if separate_sampler {
            layout_builder = layout_builder.add_indexed_binding(vk::DescriptorType::SAMPLER, stage_flags, 0, 1);
        }
        layout_builder =
            layout_builder.add_indexed_binding(params.sampling_type, stage_flags, image_binding, params.image_count);
        let storage_binding = image_binding + 1;
        if params.use_compute {
            layout_builder = layout_builder
                .add_indexed_binding(
                    vk::DescriptorType::STORAGE_IMAGE,
                    stage_flags,
                    storage_binding,
                    params.image_count,
                )
                .add_indexed_binding(vk::DescriptorType::STORAGE_BUFFER, stage_flags, storage_binding + 1, 1);
        }
        let descriptor_set_layout = layout_builder.build(device)?;
        let descriptor_set = make_descriptor_set(device, *descriptor_pool, *descriptor_set_layout)?;

        let descriptor_sampler = if separate_sampler {
            vk::Sampler::null()
        } else {
            *sampler
        };
        let image_infos: Vec<vk::DescriptorImageInfo> = image_views
            .iter()
            .map(|view| vk::DescriptorImageInfo {
                sampler: descriptor_sampler,
                image_view: **view,
                image_layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
            })
            .collect();
        let sampler_info = [vk::DescriptorImageInfo {
            sampler: *sampler,
            image_view: vk::ImageView::null(),
            image_layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
        }];
        let storage_infos: Vec<vk::DescriptorImageInfo> = color_attachment_views
            .iter()
            .map(|view| vk::DescriptorImageInfo {
                sampler: vk::Sampler::null(),
                image_view: **view,
                image_layout: vk::ImageLayout::GENERAL,
            })
            .collect();
        let buffer_info = [vk::DescriptorBufferInfo {
            buffer: vertex_buffer.get(),
            offset: 0,
            range: vk::WHOLE_SIZE,
        }];

        {
            let mut writes = Vec::new();
            if separate_sampler {
                writes.push(
                    vk::WriteDescriptorSet::builder()
                        .dst_set(descriptor_set.get())
                        .dst_binding(0)
                        .descriptor_type(vk::DescriptorType::SAMPLER)
                        .image_info(&sampler_info)
                        .build(),
                );
            }
            writes.push(
                vk::WriteDescriptorSet::builder()
                    .dst_set(descriptor_set.get())
                    .dst_binding(image_binding)
                    .descriptor_type(params.sampling_type)
                    .image_info(&image_infos)
                    .build(),
            );
            if params.use_compute {
                writes.push(
                    vk::WriteDescriptorSet::builder()
                        .dst_set(descriptor_set.get())
                        .dst_binding(storage_binding)
                        .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                        .image_info(&storage_infos)
                        .build(),
                );
                writes.push(
                    vk::WriteDescriptorSet::builder()
                        .dst_set(descriptor_set.get())
                        .dst_binding(storage_binding + 1)
                        .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
                        .buffer_info(&buffer_info)
                        .build(),
                );
            }
            unsafe { device.update_descriptor_sets(&writes, &[] as &[vk::CopyDescriptorSet]) };
        }

        // The lookup scale and bias of the format, as the shader applies them
        let use_stencil_aspect = params.subresource_range.aspect_mask == vk::ImageAspectFlags::STENCIL;
        let (lookup_scale, lookup_bias) = get_lookup_scale_bias(params.image_format, use_stencil_aspect);
        let (shader_scale, shader_bias) = params.shader_scale_bias.map_or_else(
            || {
                (
                    swizzle_scale_bias(lookup_scale, &params.component_mapping, 1.0),
                    swizzle_scale_bias(lookup_bias, &params.component_mapping, 0.0),
                )
            },
            |scale_bias| scale_bias,
        );
        let mut push_constants = [0f32; 12];
        push_constants[..4].copy_from_slice(&shader_scale);
        push_constants[4..8].copy_from_slice(&shader_bias);
        push_constants[8] = params.sampler_lod;
        let push_constant_bytes: Vec<u8> = push_constants.iter().flat_map(|value| value.to_ne_bytes()).collect();
        let push_constant_ranges = [vk::PushConstantRange {
            stage_flags,
            offset: 0,
            size: push_constant_bytes.len() as u32,
        }];
        let set_layouts = [*descriptor_set_layout];
        let pipeline_layout_info = vk::PipelineLayoutCreateInfo::builder()
            .set_layouts(&set_layouts)
            .push_constant_ranges(&push_constant_ranges);
        let pipeline_layout = Unique::new(
            device,
            unsafe { device.create_pipeline_layout(&pipeline_layout_info, None) }.vk_check("vkCreatePipelineLayout")?,
        );

        let binaries = context.get_binary_collection();

        // Render pass and framebuffer, or the shader objects of a shader object construction type
        let construction = ambient_construction_type();
        let use_shader_objects = construction.is_shader_object();
        let render_pass;
        let framebuffer;
        let graphics_pipeline;
        let compute_pipeline;
        let vertex_shader_object;
        let fragment_shader_object;
        let compute_shader_object;
        if !params.use_compute && use_shader_objects {
            render_pass = None;
            framebuffer = None;
            graphics_pipeline = None;
            compute_pipeline = None;
            compute_shader_object = None;
            let (vertex, fragment) = create_graphics_shader_objects(
                context,
                construction,
                binaries.get("tex_vert")?,
                binaries.get("tex_frag")?,
                *descriptor_set_layout,
                push_constant_ranges[0],
            )?;
            vertex_shader_object = Some(vertex);
            fragment_shader_object = Some(fragment);
        } else if !params.use_compute {
            vertex_shader_object = None;
            fragment_shader_object = None;
            compute_shader_object = None;
            let attachment_descriptions: Vec<vk::AttachmentDescription> = (0..image_count)
                .map(|_| {
                    vk::AttachmentDescription::builder()
                        .format(color_format)
                        .samples(vk::SampleCountFlags::_1)
                        .load_op(vk::AttachmentLoadOp::CLEAR)
                        .store_op(vk::AttachmentStoreOp::STORE)
                        .stencil_load_op(vk::AttachmentLoadOp::DONT_CARE)
                        .stencil_store_op(vk::AttachmentStoreOp::DONT_CARE)
                        .initial_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                        .final_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                        .build()
                })
                .collect();
            let attachment_references: Vec<vk::AttachmentReference> = (0..image_count)
                .map(|ndx| vk::AttachmentReference {
                    attachment: ndx as u32,
                    layout: vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL,
                })
                .collect();
            let subpass = vk::SubpassDescription::builder()
                .pipeline_bind_point(vk::PipelineBindPoint::GRAPHICS)
                .color_attachments(&attachment_references);
            let subpasses = [subpass];
            let render_pass_info = vk::RenderPassCreateInfo::builder()
                .attachments(&attachment_descriptions)
                .subpasses(&subpasses);
            render_pass = Some(Unique::new(
                device,
                unsafe { device.create_render_pass(&render_pass_info, None) }.vk_check("vkCreateRenderPass")?,
            ));

            let attachment_views: Vec<vk::ImageView> = color_attachment_views.iter().map(|view| **view).collect();
            framebuffer = Some(make_framebuffer(
                device,
                **render_pass.as_ref().expect("just created"),
                &attachment_views,
                render_size[0],
                render_size[1],
                1,
            )?);

            let vertex_module = create_shader_module(device, binaries.get("tex_vert")?)?;
            let fragment_module = create_shader_module(device, binaries.get("tex_frag")?)?;

            let mut state = DrawPipelineState::new(vk::PrimitiveTopology::TRIANGLE_LIST)
                .with_full_viewport(render_size[0], render_size[1]);
            state.bindings = vec![vk::VertexInputBindingDescription {
                binding: 0,
                stride: std::mem::size_of::<Vertex4Tex4>() as u32,
                input_rate: vk::VertexInputRate::VERTEX,
            }];
            state.attributes = vec![
                vk::VertexInputAttributeDescription {
                    location: 0,
                    binding: 0,
                    format: vk::Format::R32G32B32A32_SFLOAT,
                    offset: 0,
                },
                vk::VertexInputAttributeDescription {
                    location: 1,
                    binding: 0,
                    format: vk::Format::R32G32B32A32_SFLOAT,
                    offset: std::mem::offset_of!(Vertex4Tex4, tex_coord) as u32,
                },
            ];
            state.color_attachment_count = params.image_count;
            state.create_flags = params.pipeline_create_flags;
            graphics_pipeline = Some(create_draw_pipeline(
                device,
                *pipeline_layout,
                **render_pass.as_ref().expect("just created"),
                &[
                    (vk::ShaderStageFlags::VERTEX, *vertex_module),
                    (vk::ShaderStageFlags::FRAGMENT, *fragment_module),
                ],
                &state,
            )?);
            compute_pipeline = None;
        } else {
            render_pass = None;
            framebuffer = None;
            graphics_pipeline = None;
            vertex_shader_object = None;
            fragment_shader_object = None;
            if use_shader_objects {
                compute_pipeline = None;
                compute_shader_object = Some(create_compute_shader_object(
                    device,
                    construction,
                    binaries.get("tex_comp")?,
                    *descriptor_set_layout,
                    push_constant_ranges[0],
                )?);
            } else {
                compute_shader_object = None;
                let compute_module = create_shader_module(device, binaries.get("tex_comp")?)?;
                let stage = vk::PipelineShaderStageCreateInfo::builder()
                    .stage(vk::ShaderStageFlags::COMPUTE)
                    .module(*compute_module)
                    .name(b"main\0")
                    .build();
                let compute_info = vk::ComputePipelineCreateInfo::builder()
                    .stage(stage)
                    .layout(*pipeline_layout)
                    .base_pipeline_index(0)
                    .build();
                let pipelines =
                    unsafe { device.create_compute_pipelines(vk::PipelineCache::null(), &[compute_info], None) }
                        .vk_check("vkCreateComputePipelines")?;
                compute_pipeline = Some(Unique::new(device, pipelines.0[0]));
            }
        }

        // Create the command pool and buffer, and record the commands
        let cmd_pool = make_command_pool(device, queue_family_index)?;
        let cmd_buffer = allocate_command_buffer(device, *cmd_pool, vk::CommandBufferLevel::PRIMARY)?;
        let cmd = *cmd_buffer;
        begin_command_buffer(device, cmd)?;

        let color_range = vk::ImageSubresourceRange {
            aspect_mask: vk::ImageAspectFlags::COLOR,
            base_mip_level: 0,
            level_count: 1,
            base_array_layer: 0,
            layer_count: 1,
        };
        if params.use_compute {
            let pre_compute_barriers: Vec<vk::ImageMemoryBarrier> = color_images
                .iter()
                .map(|image| {
                    vk::ImageMemoryBarrier::builder()
                        .src_access_mask(vk::AccessFlags::empty())
                        .dst_access_mask(vk::AccessFlags::SHADER_WRITE)
                        .old_layout(vk::ImageLayout::UNDEFINED)
                        .new_layout(vk::ImageLayout::GENERAL)
                        .src_queue_family_index(vk::QUEUE_FAMILY_IGNORED)
                        .dst_queue_family_index(vk::QUEUE_FAMILY_IGNORED)
                        .image(image.get())
                        .subresource_range(color_range)
                        .build()
                })
                .collect();
            unsafe {
                device.cmd_pipeline_barrier(
                    cmd,
                    vk::PipelineStageFlags::TOP_OF_PIPE,
                    vk::PipelineStageFlags::COMPUTE_SHADER,
                    vk::DependencyFlags::empty(),
                    &[] as &[vk::MemoryBarrier],
                    &[] as &[vk::BufferMemoryBarrier],
                    &pre_compute_barriers,
                );
                if let Some(compute_shader) = &compute_shader_object {
                    bind_compute_shader(device, cmd, compute_shader.get());
                } else {
                    device.cmd_bind_pipeline(
                        cmd,
                        vk::PipelineBindPoint::COMPUTE,
                        **compute_pipeline.as_ref().expect("a compute run has a compute pipeline"),
                    );
                }
                device.cmd_bind_descriptor_sets(
                    cmd,
                    vk::PipelineBindPoint::COMPUTE,
                    *pipeline_layout,
                    0,
                    &[descriptor_set.get()],
                    &[] as &[u32],
                );
                device.cmd_push_constants(
                    cmd,
                    *pipeline_layout,
                    vk::ShaderStageFlags::COMPUTE,
                    0,
                    &push_constant_bytes,
                );
                device.cmd_dispatch(cmd, render_size[0], render_size[1], 1);
            }
        } else {
            let attachment_clear_values = vec![default_clear_value(color_format); image_count];
            let pre_attachment_barriers: Vec<vk::ImageMemoryBarrier> = color_images
                .iter()
                .map(|image| {
                    vk::ImageMemoryBarrier::builder()
                        .src_access_mask(vk::AccessFlags::empty())
                        .dst_access_mask(vk::AccessFlags::COLOR_ATTACHMENT_WRITE)
                        .old_layout(vk::ImageLayout::UNDEFINED)
                        .new_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                        .src_queue_family_index(vk::QUEUE_FAMILY_IGNORED)
                        .dst_queue_family_index(vk::QUEUE_FAMILY_IGNORED)
                        .image(image.get())
                        .subresource_range(color_range)
                        .build()
                })
                .collect();
            unsafe {
                device.cmd_pipeline_barrier(
                    cmd,
                    vk::PipelineStageFlags::TOP_OF_PIPE,
                    vk::PipelineStageFlags::COLOR_ATTACHMENT_OUTPUT,
                    vk::DependencyFlags::empty(),
                    &[] as &[vk::MemoryBarrier],
                    &[] as &[vk::BufferMemoryBarrier],
                    &pre_attachment_barriers,
                );

                let render_area = make_rect_2d(0, 0, render_size[0], render_size[1]);
                if let (Some(vertex_shader), Some(fragment_shader)) = (&vertex_shader_object, &fragment_shader_object) {
                    // Shader objects draw inside dynamic rendering, and every state a pipeline would hold is dynamic.
                    let rendering_attachments: Vec<vk::RenderingAttachmentInfo> = color_attachment_views
                        .iter()
                        .zip(&attachment_clear_values)
                        .map(|(view, clear_value)| {
                            vk::RenderingAttachmentInfo::builder()
                                .image_view(**view)
                                .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                                .resolve_mode(vk::ResolveModeFlags::NONE)
                                .load_op(vk::AttachmentLoadOp::CLEAR)
                                .store_op(vk::AttachmentStoreOp::STORE)
                                .clear_value(*clear_value)
                                .build()
                        })
                        .collect();
                    let rendering_info = vk::RenderingInfo::builder()
                        .render_area(render_area)
                        .layer_count(1)
                        .view_mask(0)
                        .color_attachments(&rendering_attachments);
                    device.cmd_begin_rendering(cmd, &rendering_info);

                    set_default_shader_object_dynamic_states(
                        device,
                        cmd,
                        context.get_device_extensions(),
                        vk::PrimitiveTopology::TRIANGLE_LIST,
                        false,
                        true,
                        render_size[0],
                        render_size[1],
                    );
                    let binding = vk::VertexInputBindingDescription2EXT {
                        s_type: vk::StructureType::VERTEX_INPUT_BINDING_DESCRIPTION_2_EXT,
                        next: std::ptr::null_mut(),
                        binding: 0,
                        stride: std::mem::size_of::<Vertex4Tex4>() as u32,
                        input_rate: vk::VertexInputRate::VERTEX,
                        divisor: 1,
                    };
                    let attribute = |location: u32, offset: u32| vk::VertexInputAttributeDescription2EXT {
                        s_type: vk::StructureType::VERTEX_INPUT_ATTRIBUTE_DESCRIPTION_2_EXT,
                        next: std::ptr::null_mut(),
                        location,
                        binding: 0,
                        format: vk::Format::R32G32B32A32_SFLOAT,
                        offset,
                    };
                    device.cmd_set_vertex_input_ext(
                        cmd,
                        &[binding],
                        &[
                            attribute(0, 0),
                            attribute(1, std::mem::offset_of!(Vertex4Tex4, tex_coord) as u32),
                        ],
                    );
                    let blend_equation = vk::ColorBlendEquationEXT {
                        src_color_blend_factor: vk::BlendFactor::ONE,
                        dst_color_blend_factor: vk::BlendFactor::ZERO,
                        color_blend_op: vk::BlendOp::ADD,
                        src_alpha_blend_factor: vk::BlendFactor::ONE,
                        dst_alpha_blend_factor: vk::BlendFactor::ZERO,
                        alpha_blend_op: vk::BlendOp::ADD,
                    };
                    device.cmd_set_color_blend_enable_ext(cmd, 0, &vec![vk::FALSE; image_count]);
                    device.cmd_set_color_blend_equation_ext(cmd, 0, &vec![blend_equation; image_count]);
                    device.cmd_set_color_write_mask_ext(
                        cmd,
                        0,
                        &vec![
                            vk::ColorComponentFlags::R
                                | vk::ColorComponentFlags::G
                                | vk::ColorComponentFlags::B
                                | vk::ColorComponentFlags::A;
                            image_count
                        ],
                    );

                    let mesh_features = get_mesh_shader_features(context);
                    bind_graphics_shaders(
                        device,
                        cmd,
                        vertex_shader.get(),
                        vk::ShaderEXT::null(),
                        vk::ShaderEXT::null(),
                        vk::ShaderEXT::null(),
                        fragment_shader.get(),
                        mesh_features.task_shader == vk::TRUE,
                        mesh_features.mesh_shader == vk::TRUE,
                    );
                } else {
                    let begin_info = vk::RenderPassBeginInfo::builder()
                        .render_pass(**render_pass.as_ref().expect("a graphics run has a render pass"))
                        .framebuffer(**framebuffer.as_ref().expect("a graphics run has a framebuffer"))
                        .render_area(render_area)
                        .clear_values(&attachment_clear_values);
                    device.cmd_begin_render_pass(cmd, &begin_info, vk::SubpassContents::INLINE);

                    device.cmd_bind_pipeline(
                        cmd,
                        vk::PipelineBindPoint::GRAPHICS,
                        **graphics_pipeline.as_ref().expect("a graphics run has a pipeline"),
                    );
                }
                device.cmd_bind_descriptor_sets(
                    cmd,
                    vk::PipelineBindPoint::GRAPHICS,
                    *pipeline_layout,
                    0,
                    &[descriptor_set.get()],
                    &[] as &[u32],
                );
                device.cmd_push_constants(
                    cmd,
                    *pipeline_layout,
                    vk::ShaderStageFlags::FRAGMENT,
                    0,
                    &push_constant_bytes,
                );
                device.cmd_bind_vertex_buffers(cmd, 0, &[vertex_buffer.get()], &[0]);
                device.cmd_draw(cmd, params.vertices.len() as u32, 1, 0, 0);
                if use_shader_objects {
                    device.cmd_end_rendering(cmd);
                } else {
                    device.cmd_end_render_pass(cmd);
                }
            }
        }
        end_command_buffer(device, cmd)?;

        submit_commands_and_wait(device, queue, cmd)?;

        self.verify_image(&texture, &color_images, color_format, component_mask)
    }

    /// `ImageSamplingInstance::verifyImage`
    fn verify_image(
        &self,
        texture: &TestTexture,
        color_images: &[ImageWithMemory<'_>],
        color_format: vk::Format,
        component_mask: [bool; 4],
    ) -> TestOutcome {
        let context = self.context;
        let params = &self.params;
        let sampler_params = &params.sampler_params;
        let limits = context.get_device_properties().limits;
        let render_size = params.render_size;

        // \note The colour buffer is used to capture coordinates - not sampled texture values
        let coord_format = TextureFormat::new(ChannelOrder::RGBA, ChannelType::FLOAT);
        let vertex_shader = ColorVertexShader::new();
        let fragment_shader = ColorFragmentShader::new(coord_format, None, false);
        let program = Program {
            vertex_shader: &vertex_shader,
            fragment_shader: &fragment_shader,
            geometry_shader: None,
        };
        let mut ref_renderer = ReferenceRenderer::new(render_size[0], render_size[1], coord_format, None)?;
        let use_stencil_aspect = params.subresource_range.aspect_mask == vk::ImageAspectFlags::STENCIL;
        let (lookup_scale, lookup_bias) = get_lookup_scale_bias(params.image_format, use_stencil_aspect);

        // Render out coordinates
        {
            let render_state = RenderState::new(
                ref_renderer.get_viewport_state(),
                limits.sub_pixel_precision_bits as i32,
            );
            let vertices: Vec<Vertex4Rgba> = params
                .vertices
                .iter()
                .map(|vertex| Vertex4Rgba {
                    position: vertex.position,
                    color: vertex.tex_coord,
                })
                .collect();
            ref_renderer.draw(&program, &render_state, PrimitiveType::Triangles, &vertices);
        }

        // Verify results
        let sampler = SamplerVerification {
            wrap: [
                map_vk_sampler_address_mode(sampler_params.address_mode_u),
                map_vk_sampler_address_mode(sampler_params.address_mode_v),
                map_vk_sampler_address_mode(sampler_params.address_mode_w),
            ],
            normalized: !sampler_params.unnormalized_coordinates,
            min_filter: map_vk_min_tex_filter(sampler_params.min_filter, sampler_params.mipmap_mode),
            mag_filter: if sampler_params.mag_filter == vk::Filter::LINEAR {
                FilterMode::Linear
            } else {
                FilterMode::Nearest
            },
            border: sampler_params.tcu_border_color(),
        };
        let _ambient_reduction = AmbientReduction::enter(match sampler_params.reduction_mode {
            Some(vk::SamplerReductionMode::MIN) => Some(ReductionMode::Min),
            Some(vk::SamplerReductionMode::MAX) => Some(ReductionMode::Max),
            _ => None,
        });
        let reference_lod = (sampler_params.mip_lod_bias + params.sampler_lod).clamp(
            sampler_params.min_lod.min(sampler_params.max_lod),
            sampler_params.max_lod,
        );
        let lod_error = 1.0 / ((1u32 << limits.mipmap_precision_bits) - 1) as f32;
        let lod_bounds = (reference_lod - lod_error, reference_lod + lod_error);
        let subresource = resolve_subresource_range(texture, &params.subresource_range);

        let coord_access = ref_renderer.get_access();
        let mut error_mask = TextureLevel::new(
            TextureFormat::new(ChannelOrder::RGBA, ChannelType::UNORM_INT8),
            render_size[0],
            render_size[1],
            1,
        )?;

        let is_nearest_only =
            sampler_params.min_filter == vk::Filter::NEAREST && sampler_params.mag_filter == vk::Filter::NEAREST;

        // Set precision requirements - very low for these tests as the point of the test is not to validate accuracy.
        let mut format_bit_depth = [7i32; 4]; // Approximation for almost all compressed formats that seems to work well.
        if !is_compressed_format(params.image_format) {
            format_bit_depth = get_texture_format_bit_depth(
                map_vk_format(params.image_format)
                    .ok_or_else(|| TestError::NotPorted(format!("no texture format for {:?}", params.image_format)))?,
            );
        } else if params.image_format == vk::Format::BC5_UNORM_BLOCK
            || params.image_format == vk::Format::BC5_SNORM_BLOCK
        {
            format_bit_depth = [5; 4]; // Approximation, seems to work well.
        }
        let swizzled_scale = swizzle_scale_bias(lookup_scale, &params.component_mapping, 1.0);
        let accurate_bits: [i32; 4] =
            format_bit_depth.map(|bits| (bits.min(8) - if is_nearest_only { 1 } else { 2 }).max(0));
        let mut lookup_precision = LookupPrecision {
            coord_bits: [17, 17, 17],
            uvw_bits: [5, 5, 5],
            color_mask: component_mask,
            color_threshold: std::array::from_fn(|c| compute_fixed_point_error(accurate_bits[c]) / swizzled_scale[c]),
            border_color: [0.0; 4],
        };

        // Account for sRGB conversion precision.
        if texture.get_texture_format().order.is_srgb() {
            for threshold in lookup_precision.color_threshold.iter_mut() {
                *threshold += 4.0 / 255.0;
            }
        }

        let mut texture_copy = None;
        if is_combined_depth_stencil_type(texture.get_texture_format().type_) {
            // The verification loop does not support reading from combined depth stencil texture levels: get rid of the other aspect.
            let format = if subresource.aspect_mask == vk::ImageAspectFlags::STENCIL {
                get_effective_depth_stencil_texture_format(texture.get_texture_format(), DepthStencilMode::Stencil)
            } else {
                let channel_type = match texture.get_texture_format().type_ {
                    ChannelType::UNSIGNED_INT_16_8_8 => ChannelType::UNORM_INT16,
                    ChannelType::UNSIGNED_INT_24_8 | ChannelType::UNSIGNED_INT_24_8_REV => ChannelType::UNORM_INT24,
                    ChannelType::FLOAT_UNSIGNED_INT_24_8_REV => ChannelType::FLOAT,
                    other => {
                        return Err(TestError::InternalError(format!(
                            "Unhandled texture format type {other:?}"
                        )));
                    }
                };
                TextureFormat::new(ChannelOrder::D, channel_type)
            };
            texture_copy = Some(texture.copy(format)?);
        }
        let verified_texture = texture_copy.as_ref().unwrap_or(texture);

        let mut compare_ok_all = true;
        for color_image in color_images {
            // Read back the result image
            let attachment_access = if params.use_compute {
                vk::AccessFlags::SHADER_WRITE
            } else {
                vk::AccessFlags::COLOR_ATTACHMENT_WRITE
            };
            let attachment_layout = if params.use_compute {
                vk::ImageLayout::GENERAL
            } else {
                vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL
            };

            let result = read_color_attachment_with_access(
                context,
                color_image.get(),
                color_format,
                (render_size[0], render_size[1]),
                attachment_layout,
                attachment_access,
            )?;
            let result_access = result.get_const_access();
            let compare_ok = validate_with_swizzle(
                verified_texture,
                params.image_view_type,
                &subresource,
                &sampler,
                &params.component_mapping,
                &coord_access,
                lod_bounds,
                &mut lookup_precision,
                lookup_scale,
                lookup_bias,
                &result_access,
                &mut error_mask,
            )?;

            compare_ok_all = compare_ok_all && compare_ok;
        }

        if compare_ok_all {
            Ok(TestStatus::pass("Result image matches reference"))
        } else {
            Ok(TestStatus::fail("Image mismatch"))
        }
    }
}

impl TestInstance for ImageSamplingInstance<'_> {
    fn iterate(&mut self) -> TestOutcome {
        self.run()
    }
}
